interface Named { fn name() -> text }
class Person(let value: text) implements Named { override fn name() -> text = self.value }
class Student(let student_name: text) extends Person { override fn name() -> text = "Student " + self.student_name }
fn label(item: Named) -> text = item.name()
let person: Person = Student("base","Aki")
let named: Named = person
print(label(named), text(person))

class Box[T](let value: T) { fn get() -> T = self.value }
let box: Box[int] = Box(42)
print(box.get())

abstract class Shape() { abstract fn area() -> int }
class Square(let side: int) extends Shape { override fn area() -> int = self.side*self.side }
let s: Shape = Square(4)
print(s.area())

@entity
