interface Named { fn name() -> text }
abstract class Base(let value: int) implements Named {
    override fn name() -> text = "base"
    abstract fn kind() -> text
}
class Child(let extra: text) extends Base {
    override fn kind() -> text = self.extra
}
fn identity[T](value: T) -> T = value
let child: Named = Child(5, "child")
print(child.name(), identity("generic"))

